INSERT INTO formulacion_144
 (id, formulario_id, nombre_borrador, anio, linea_estrategica, objetivo, estrategia, motor_desarrollo, proyecto, meta_resultado, ponderacion_proyectos, actividad_proyecto, ponderacion_actividades, responsable_formulacion, id_indicador, gestionado_facultades, nombre_indicador, formula_medicion, frecuencia_medicion, unidad_medida, tipo_medicion, descripcion_indicador, planes_institucionales, linea_base_meta, anio_base_meta, meta_s1, meta_s2, meta_programada, meta_ejecutada, porcentaje_avance, semestre1_seguimiento, semestre2_seguimiento, logros, limites, observacion_estado, acciones_fortalecimiento, estado_formulacion, estado_seguimiento, solicitud_estado_formulacion, solicitud_estado_seguimiento, semaforo_etapa_formulacion, semaforo_etapa_seguimiento, semaforo_rechazo_etapa_formulacion, semaforo_rechazo_etapa_seguimiento, fecha_publicacion_formulacion, creado_por)
VALUES
(@base+1, @formulario, 'Sistema de evaluación del impacto de las estrategias de permanencia y graduación estudiantil', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '1. Ampliar las capacidades institucionales para el mejoramiento de la cobertura de los programas de bienestar y fortalecer los factores protectores de la permanencia y graduación estudiantil.', 'Fortalecimiento para la permanencia y graduación oportuna', 'Promoción al acceso, permanencia y graduación estudiantil', 'Establecer informes de evaluación para controlar el impacto de las estrategias de permanencia y graduación que permita fortalecer el proceso formativo.', 20.00, 'Revisar y diseñar un modelo de evaluación en relación al impacto de las estrategias de permanencia y graduación.', 15.00, 'Dpto. de Desarrollo Humano', 'PDI', '0', 'Sistema de evaluación del impacto de las estrategias de permanencia y graduación estudiantil', 'Documento de evaluación periódica en relación con el impacto de las estrategias de permanencia y graduación estudiantil por trienio', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '1', 1, '0', '1', '1.00', '1.00', 100.00, 1.00, NULL, 'Se cuenta con un documento de informe de evaluación de impacto de las estrategias del Programa de Apoyo a la permanencia y Graduación estudiantil, el cual fue el resultado del análisis realizado a la Base de datos de atendidos por el programa en 2024-2, comparado con la base de estudiantes considerados desertores de 2025-2, teniendo en cuenta que de acuerdo al MEN, un estudiante es considerado desertor de un programa si permanece por dos periodos seguidos o más sin matrícula y no se reporta como graduado o suspendido por temas disciplinarios.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         - Mediante este análisis se evidencia que del total de estudiantes atendidos por las estrategias de permanencia el 9,65% ha desertado, de acuerdo a los datos de deserción interna. Sin tener en cuenta que hay estudiantes que pueden estar como desertores, por su situación de grado; es decir que pueden estar como desertores, pero en realidad estan pendientes de grado.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+2, @formulario, 'Tasa de deserción anual', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '2. Fortalecer las competencias del ser en concordancia con las necesidades de la comunidad universitaria enmarcadas en las habilidades y destrezas para un ser integral.', 'Fortalecimiento para la permanencia y graduación oportuna', 'Promoción al acceso, permanencia y graduación estudiantil', 'Aumentar el índice de permanencia y oportuna graduación estudiantil basado en el acompañamiento institucional, psicosocial, académico y socioeconómico en cada etapa del  proyecto de vida universitario del estudiante.', 20.00, 'Desarrollar las estrategias de apoyo a la permanencia y graduación oportuna en articulación con las actividades académicas.', 15.00, 'Dpto. de Desarrollo Humano', 'PDI', '0', 'Tasa de deserción anual', '(Desertores en Período (t) / Matriculados en Período (t-2)) x 100%', 'Semestral', 'Porcentaje', 'Límite', 'En la medición de Plan de acción se utiliza la medición interna, mientras que en el Plan de Desarrollo SPADIES', '[]', '8.3%', 9, '9%', '9%', '9.00', '8.00', 100.00, NULL, 8.00, 'De acuerdo al Sistema SPADIES, el último reporte de la tasa de deserción anual es a corte 2024-2, el cual es de 8.64%, cifra que es inferior al promedio nacional que es de 12.29%. \nEn relación a la estimación interna, la Deserción Anual a corte 2026-1 es 8%', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+3, @formulario, 'Diseño de metodología correspondiente a la Política de Permanencia y Graduación estudiantil en la Universidad del Atlántico', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '1. Ampliar las capacidades institucionales para el mejoramiento de la cobertura de los programas de bienestar y fortalecer los factores protectores de la permanencia y graduación estudiantil.', 'Fortalecimiento para la permanencia y graduación oportuna', 'Promoción al acceso, permanencia y graduación estudiantil', 'Diseñar e implementar la Política de Permanencia y Graduación estudiantil.', 20.00, 'Diseñar documento de metodología correspondiente a la Política de Permanencia y Graduación estudiantil', 15.00, 'Dpto. de Desarrollo Humano', 'PDI', '0', 'Diseño de metodología correspondiente a la Política de Permanencia y Graduación estudiantil en la Universidad del Atlántico', 'Aprobación de la política', 'Semestral', 'Porcentaje', 'Nuevo gestionado durante la vigencia', '1. aval Bienestar (10%\n2. aval Juridica (20)\n3. Aval Financiera (20)\n4. Avan Consejo Academico (30)\n5. radicacion consejo Superior (20)', '[]', '0%', 100, '0%', '100%', '100.00', '0.00', 0.00, 0.00, NULL, 'Se proyecta en el segundo periodo realizar los avances pertinentes para proceder con la revision y aprobaciones respectivas.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+4, @formulario, 'Diseño y elaboración de un informe semestral que consolide las estrategias desde Bienestar para las sedes regionales', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '1. Ampliar las capacidades institucionales para el mejoramiento de la cobertura de los programas de bienestar y fortalecer los factores protectores de la permanencia y graduación estudiantil.', 'Fortalecimiento para la permanencia y graduación oportuna', 'Promoción al acceso, permanencia y graduación estudiantil', 'Evaluar el impacto de las estrategias de permanencia y graduación en las sedes regionales', 20.00, 'Diseñar un informe en relación con las estrategias de bienestar direccionadas a las sedes regional', 15.00, 'Dpto. de Desarrollo Humano', 'PA', '0', 'Diseño y elaboración de un informe semestral que consolide las estrategias desde Bienestar para las sedes regionales', 'Informe con relación a las estrategias desarrolladas en las sedes regionales', 'Semestral', 'Unidad', 'Nuevo gestionado durante la vigencia', 'El informe contiene todas las áreas de Bienestar Universitario', '[]', '2', 2, '1', '1', '2.00', '1.00', 50.00, 1.00, NULL, 'Actividades desarrolladas en las sedes: \nEn ambas sedes se realizaron acciones de inducción a estudiantes de primer ingreso y a padres de familia, con participación de directivos y actividades de VIVE Tu UA.\n\nDe manera general, las estrategias implementadas incluyeron:\n\n- Asesoría y consejería psicológica, con atención presencial y virtual a estudiantes remitidos o que solicitaron apoyo voluntariamente.\n- Orientación académica, dirigida a estudiantes con bajo rendimiento, vinculados al programa PIC o remitidos por docentes y coordinadores.\n - Talleres de formación integral y orientación académica, con temáticas diversas para fortalecer la formación personal y académica.\n- Tutoría académica, brindada por docentes tutores a estudiantes en situación de vulnerabilidad académica.\n- Sistema de Alertas Tempranas (SAT), con acompañamiento a estudiantes priorizados por las Facultades.\n- Trabajo social, con atenciones presenciales puntuales y mayoritariamente remotas.\n- Programas complementarios como POIL y SAEC, que ofrecieron espacios de inserción laboral y actividades de acompañamiento académico.\n- Monitores solidarios, cuya ejecución se realizo hasta el proceso de seleccion de los aspirantes. Se espera continuar en el segundo periodo del año.', '', 'Durante el periodo 2026‑1, las sedes regionales enfrentaron limitaciones por la ausencia de personal permanente adscrito. En Sabanalarga se contó con dos psicólogas de permanencia, mientras que en Suan no hubo apoyo fijo. La presencia de profesionales como el psicólogo PIC resulta clave para fortalecer el trabajo en equipo y garantizar la cobertura de los servicios de la Vicerrectoría de Bienestar Universitario.', 'Las estrategias que dependen de personal de sede norte se ejecutaron de manera esporádica, debido a la necesidad de desplazamientos y recursos económicos adicionales. Se recomienda que las visitas de las secciones funcionales de Bienestar se organicen de forma escalonada, para ampliar la cobertura y optimizar la atención. Para el segundo semesgtre se proyecta contar con 2 profesionales al frente de las estrategias del programa de permanencia  y la apertura al igual que el personal asignado para los puntos violetas en ambas sedes y proximamente en la sede de soledad.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+5, @formulario, 'Estudiantes en bajo rendimiento atendidos en las estrategias de permanencia de facultades.', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '1. Ampliar las capacidades institucionales para el mejoramiento de la cobertura de los programas de bienestar y fortalecer los factores protectores de la permanencia y graduación estudiantil.', 'Fortalecimiento para la permanencia y graduación oportuna', 'Promoción al acceso, permanencia y graduación estudiantil', 'Fortalecer la atención de los estudiantes en bajo rendimiento como estrategias de permanencia', 20.00, 'Implementar las atenciones de los estudiantes en bajo rendimiento como estrategias de permanencia', 20.00, 'Dpto. de Desarrollo Humano', 'PA', '1', 'Estudiantes en bajo rendimiento atendidos en las estrategias de permanencia de facultades.', 'N° de estudiantes de bajo rendimiento atendidos en tutoría académica / total de estudiantes de bajo rendimiento de la Facultad * 100', 'Semestral', 'Porcentaje', 'Último valor reportado', '', '[]', '53.81%', 50, '50%', '50%', '50.00', '58.10', 116.20, 58.10, NULL, '1,241 ESTUDIANTES EN BAJO RENDIMIENTO POR FACULTAD DE LOS CUALES 721 FUERON ATENDIDOS', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+6, @formulario, 'Estudiantes de primer semestre atendidos en las estrategias de permanencia de facultades.', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '1. Ampliar las capacidades institucionales para el mejoramiento de la cobertura de los programas de bienestar y fortalecer los factores protectores de la permanencia y graduación estudiantil.', 'Fortalecimiento para la permanencia y graduación oportuna', 'Promoción al acceso, permanencia y graduación estudiantil', 'Fortalecer la atención de los estudiantes primer semestre como estrategias de permanencia', 20.00, 'Implementar las atenciones de los estudiantes primer semestre como estrategias de permanencia', 20.00, 'Dpto. de Desarrollo Humano', 'PA', '1', 'Estudiantes de primer semestre atendidos en las estrategias de permanencia de facultades.', 'N° de estudiantes de primer semestre atendidos en tutoría SAT / total de estudiantes de primer semestre que contestan la encuesta SAT de la Facultad * 100', 'Semestral', 'Porcentaje', 'Último valor reportado', '', '[]', '7%', 50, '50%', '50%', '50.00', '52.52', 105.04, 52.52, NULL, '377 ESTUDIANTES EN RIESGO GENERAL ALTO Y CRÍTICO SEGÚN SAT DE LOS CUALES 198 FUERON ATENDIDOS', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+7, @formulario, 'Propuesta normativa y procedimental del programa Plan Padrino', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '1. Ampliar las capacidades institucionales para el mejoramiento de la cobertura de los programas de bienestar y fortalecer los factores protectores de la permanencia y graduación estudiantil.', 'Fortalecimiento para la permanencia y graduación oportuna', 'Fortalecimiento de ayudas socioeconómicas para el éxito estudiantil', 'Diseñar e implementar el programa de Plan Padrino para el sostenimiento de mínimo 200 estudiantes en riesgo de deserción, impulsando el aporte voluntario de entes territoriales, egresados, empresarios y docentes.', 20.00, 'Diseñar e implementar el programa Plan Padrino en beneficio de la población estudiantil en alto riesgo de deserción', 40.00, 'Vice de Bienestar Universitario', 'PR-PDI', '0', 'Propuesta normativa y procedimental del programa Plan Padrino', 'N° de estudiantes beneficiados por el Programa Plan Padrino', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Se cuenta la estudiante que se ha beneficiado durante la vigencia', '[]', '0', 40, '0', '40', '40.00', '0.00', 0.00, 0.00, NULL, '2026-1: Ha sido complejo buscar padrinos y su respectivo aporte a los estudintes de la universidad, al no haberse concretado padrinos, no se han tenido estudiantes beneficiarios.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+8, @formulario, 'Diseño de evaluación del impacto de las estrategias socio-económicas para la permanencia y graduación', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '1. Ampliar las capacidades institucionales para el mejoramiento de la cobertura de los programas de bienestar y fortalecer los factores protectores de la permanencia y graduación estudiantil.', 'Fortalecimiento para la permanencia y graduación oportuna', 'Fortalecimiento de ayudas socioeconómicas para el éxito estudiantil', 'Conocer el impacto de las estrategias socio - económicas en la permanencia y graduación oportuna.', 20.00, 'Medir el impacto de las estrategias socio - económicas en la permanencia y graduación oportuna', 60.00, 'Vice de Bienestar Universitario', 'PA', '0', 'Diseño de evaluación del impacto de las estrategias socio-económicas para la permanencia y graduación', 'N° de estrategias del programa de Fortalecimiento de ayudas socioeconómicas para el éxito estudiantil con su sistema de medición construido', 'Semestral', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Construir el documento consolidado y la metodología a seguir.', '[]', '0', 1, '0', '1', '1.00', '0.00', 0.00, 0.00, NULL, '2026-1: No se ha realizado la medición de las estrategias.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+9, @formulario, 'Incremento en la favorabilidad de los resultados de la encuesta de percepción de cultura ciudadana y Derechos Humanos', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '6. Contribuir al bienestar social mediante la participación y promoción de espacios universitarios para la resolución pacífica de conflictos y la construcción de una sociedad y de un Estado justo, participativo y democrático, aportando así a la paz del país.', 'Cultura ciudadana, cultura política, equidad de género e inclusión', 'Cultura ciudadana, equidad y conveniencia', 'Estimular el desarrollo de las relaciones constructivas entre los miembros de la comunidad universitaria con base en la difusión y práctica de valores de respeto a la dignidad humana y a la diversidad, alcanzando un incremento del 6% en los resultados de percepción de cultura ciudadana y la Política de Género.', 16.00, 'Aplicar la encuesta de percepción de cultura ciudadana y DDHH, analizar resultados y diseñar estrategias.', 25.00, 'Dpto. de Desarrollo Humano', 'PDI', '0', 'Incremento en la favorabilidad de los resultados de la encuesta de percepción de cultura ciudadana y Derechos Humanos', 'Informe con línea base del análisis de la encuesta de percepción de cultura ciudadana y Derechos Humanos', 'Anual', 'Unidad', 'Acumulado', '', '[]', '0', 1, '0', '1', '1.00', '0.00', 0.00, 0.00, NULL, 'La encuesta aplicada en el periodo 2025-1 refleja una favorabilidad general del 46,29 %.                                        Para el periodo 2026-1, el instrumento fue actualizado con preguntas más cortas y puntuales, buscando mejorar la claridad y la participación estudiantil.\n\nActualmente, el análisis de los resultados del 2026-1 se encuentra en proceso, y se espera que permita comparar la evolución de las percepciones institucionales y orientar acciones de mejora en las dimensiones evaluadas.', '', 'La encuesta aplicada en el periodo 2025-1 refleja una favorabilidad general del 46,29 %, frente a un 53,71 % de percepción negativa, lo que evidencia la necesidad de fortalecer las estrategias institucionales orientadas a la convivencia, la seguridad y la promoción de los derechos humanos. Los resultados más positivos se concentraron en Infraestructura y Sentido de Pertenencia (56,08 %) y en Ciudadanía Universitaria y Sistemas de Participación (53,66 %), aspectos que muestran avances en el compromiso y la identificación de la comunidad universitaria con la institución.\n\nDurante el periodo 2025-2, no se logró realizar la encuesta, debido a ajustes metodológicos y operativos en el proceso de aplicación.', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+10, @formulario, 'Diseño y construcción del documento metodológico para la construcción de la Política de Género en la Universidad del Atlántico', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '6. Contribuir al bienestar social mediante la participación y promoción de espacios universitarios para la resolución pacífica de conflictos y la construcción de una sociedad y de un Estado justo, participativo y democrático, aportando así a la paz del país.', 'Cultura ciudadana, cultura política, equidad de género e inclusión', 'Cultura ciudadana, equidad y conveniencia', 'Estimular el desarrollo de las relaciones constructivas entre los miembros de la comunidad universitaria con base en la difusión y práctica de valores de respeto a la dignidad humana y a la diversidad, alcanzando un incremento del 6% en los resultados de percepción de cultura ciudadana y la Política de Género.', 16.00, 'Elaborar el documento metodológico para la construcción de la Política de Género', 25.00, 'Dpto. de Desarrollo Humano', 'PDI', '0', 'Diseño y construcción del documento metodológico para la construcción de la Política de Género en la Universidad del Atlántico', 'Política de género aprobada por el Consejo Académico.', 'Semestral', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Borrador enviado para estudio al Consejo Académico.\n\nPropuesta de la política de género enviada a Consejo Superior.', '[]', '0', 1, '0', '1', '1.00', '0.00', 0.00, 0.00, NULL, 'Durante el semestre 2025-2, las expertas encargadas de la formulación de la Política Institucional de Género presentaron avances en la estructura del documento. Se proyecta su validación y socialización en el siguiente periodo académico.                                                                                                                                         En el 2026-1 se elaboro, proyecto y radico el borrador del Proyecto de Acuerdo Superior "Por medio del cual se establece la Política Institucional de Inclusión, Equidad e Igualdad de Oportunidades para Mujeres, Hombres y Diversidades de la Universidad del Atlántico", para estudio y análisis por parte del Consejo Superior.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+11, @formulario, 'Eventos desarrollados en el marco del proyecto "Diálogo de Desarrollo Institucional"', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '3. Articular los procesos administrativos y académicos mediante el uso eficiente de los recursos financieros, tecnológicos y humanos.', 'Cultura ciudadana, cultura política, equidad de género e inclusión', 'Cultura ciudadana, equidad y conveniencia', 'Institucionalizar el proyecto "Diálogos de Desarrollo Institucional” como escenario para pensar nuestra universidad con la participación de la comunidad universitaria, con un mínimo de 9 hojas de ruta derivadas del proyecto.', 16.00, 'Elaborar el documento metodológico para la implementación del proyecto "Diálogo de Desarrollo Institucional"', 25.00, 'Dpto. de Desarrollo Humano', 'PR-PDI', '0', 'Eventos desarrollados en el marco del proyecto "Diálogo de Desarrollo Institucional"', 'N° de hojas de ruta generadas a partir de los espacios de diálogo desarrollados', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', 'De cada Dialogo de Desarrollo Institucional pueden tener como producto una Hoja de ruta, el cual es una herramienta visual que describe la dirección y el progreso de un proyecto, producto o iniciativa a lo largo del tiempo. Para este caso, se detalla los objetivos, tareas y cronogramas de un proyecto o acción específico.', '[]', '5', 3, '1', '2', '3.00', '3.00', 100.00, 3.00, NULL, 'Durante el periodo evaluado se desarrollaron 3 hojas de ruta generadas en los dialogos institucionales realizados con diferentes enfoques.                                                                                                                        1. Mesa de garantias con voceros, representantes u diversos lideres, para seguimiento de los compromisos     2. concertacion con organizaciones para la coordinacion de acciones en conmemoracion del dia del estudiante caido                                                                                                                                             3. Dialogo institucional con organizaciones estudiantiles y defensoras de derechos humanos para la coordinacion de acciones de mejora.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+12, @formulario, 'Programa "Yo Cuido la UA"', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '2. Fortalecer las competencias del ser en concordancia con las necesidades de la comunidad universitaria enmarcadas en las habilidades y destrezas para un ser integral.', 'Cultura ciudadana, cultura política, equidad de género e inclusión', 'Cultura ciudadana, equidad y conveniencia', 'Promover el programa  "Yo Cuido la UA" para el estímulo de la cultura de compromiso y cuidado de la infraestructura física y tecnológica institucional.', 16.00, 'Gestionar campañas de sensibilización hacia la comunidad universitaria para el cuidado de la infraestructura', 25.00, 'Dpto. de Desarrollo Humano', 'PR-PA', '0', 'Programa "Yo Cuido la UA"', 'Número de campañas ejecutadas dirigidas a cada estamento (trabajadores, docentes y estudiantes)', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '9', 7, '0', '7', '7.00', '2.00', 28.57, 2.00, NULL, 'Durante el semestre 2026-1 se realizaron 2 campañas  que permitieron:                                                                                                                                                                                                                                             Fortalecer el bienestar universitario, fomentar el respeto, la inclusión y la construcción de ciudadanía dentro del entorno académico. Promover la armonía y disfrute de los espacio en común y fortalecer los vínculos con otras dependencias de la universidad.                                                                                                                                                        1, "Campus vivo: Territorio de Cuidado y Dignidad" se llevo a cado en todas las sedes de la universidad                                                                                                                                                                                                        2, “Chazas de la ua “ campaña de concientizacion para el uso responsable de los espacios comunes en la universidad.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+13, @formulario, 'Fortalecer la apropiación cultural e identidad de la región Caribe', 2026, 'Bienestar Universitario, Salud mental positiva, Inclusión y Democracia.', 'Fomentar el desarrollo del ser integral en las dimensiones ética, intelectual, cultural, deportivo, artística, física, psíquica, afectiva, social y ambiental, para lograr una comunidad universitaria con bienestar y sana convivencia, lo cual contribuye al mejoramiento de las condiciones de calidad de vida y salud mental, en un contexto pluralista, participativo e incluyente.', '7. Fortalecimiento del arte, la cultura y el deporte que aportan significativamente al desarrollo humano integral y al fortalecimiento social.', 'Cultura ciudadana, cultura política, equidad de género e inclusión', 'Territorio artístico y cultural que construye una sociedad diversa e inclusiva', 'Estimular la apropiación cultural e identidad de la región Caribe, a través del reconocimiento de las herencias ancestrales frente al legado que como comunidad académica construimos para la sociedad, y los diálogos intergeneracionales y multiestamentarios para la construcción del ser integral.', 7.00, 'Gestionar actividades de apropiación cultural e identidad de la región Caribe frente al legado de las herencias ancestrales mediante diálogos intergeneracionales y multiestamentarios.', 100.00, 'Vice de Bienestar Universitario', 'PR-PA', '0', 'Fortalecer la apropiación cultural e identidad de la región Caribe', 'N° de actividades en relación con la apropiación cultural e identidad de la región Caribe', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '18', 10, '0', '10', '10.00', '6.00', 60.00, 6.00, NULL, '2026-1: Comparsa Mar y rio (febrero - Carnaval), ASCUN Caribe teatro y danza (Mayo), Sn Martin dance fest -Danza Atlantico, Dia de la danza - Delia Zapata (abril), V / IMPROMPTVS / ATLAS /EntreRedes / Salao (Junio-Bogotá Barranquilla) circulación artes vivas en el caribe, 1er encuentro de bullerengue,', '', 